import itertools

# We have 6 vertices: 0,1,2,3,4,5
# All possible edges (undirected, u < v)
all_edges = [(u,v) for u in range(6) for v in range(u+1,6)]
print("Total possible edges:", len(all_edges))

# We need a maximal triangle-free graph.
# Triangle-free: no triple (i,j,k) such that all three edges (i,j), (i,k), (j,k) are present.
# Maximal: for every non-edge (u,v) not in the graph, adding it would create a triangle.

# Let's brute force all subsets of edges (2^15 = 32768, manageable)
solutions = []
for mask in range(1 << len(all_edges)):
    # Check fixed edge (3,5) is present
    edge_35_idx = all_edges.index((3,5))
    if not (mask >> edge_35_idx) & 1:
        continue

    edges = [all_edges[i] for i in range(len(all_edges)) if (mask >> i) & 1]

    # Check triangle-free
    triangle_free = True
    for i in range(6):
        for j in range(i+1,6):
            for k in range(j+1,6):
                e1 = (i,j) in edges or (j,i) in edges
                e2 = (i,k) in edges or (k,i) in edges
                e3 = (j,k) in edges or (k,j) in edges
                if e1 and e2 and e3:
                    triangle_free = False
                    break
            if not triangle_free:
                break
        if not triangle_free:
            break

    if not triangle_free:
        continue

    # Check maximal: for every non-edge, adding it creates a triangle
    maximal = True
    for e in all_edges:
        if e not in edges:
            # Try adding this edge
            test_edges = edges + [e]
            # Check if triangle forms
            has_triangle = False
            for i in range(6):
                for j in range(i+1,6):
                    for k in range(j+1,6):
                        e1 = (i,j) in test_edges or (j,i) in test_edges
                        e2 = (i,k) in test_edges or (k,i) in test_edges
                        e3 = (j,k) in test_edges or (k,j) in test_edges
                        if e1 and e2 and e3:
                            has_triangle = True
                            break
                    if has_triangle:
                        break
                if has_triangle:
                    break
            if not has_triangle:
                maximal = False
                break

    if maximal:
        solutions.append(edges)

print(f"Found {len(solutions)} solutions")
for sol in solutions[:5]:
    print(sol)

